#include "stdlib/random/base/tinymt32.h"
#include "stdlib/random/base/shared.h"
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

// Forward declarations:
static inline int8_t next( struct BasePRNGObject *obj, uint64_t *out );
static inline int8_t normalized( struct BasePRNGObject *obj, double *out );
static inline void tinymt32_free( struct BasePRNGObject *obj );

static inline void create_state( uint32_t *state, uint32_t s );
static inline void next_state( uint32_t *state, uint32_t mat1, uint32_t mat2, uint32_t tmat );
static inline uint32_t temper( const uint32_t *state, uint32_t mat1, uint32_t mat2, uint32_t tmat );

// Define constants used by the algorithm:
static const int32_t MIN_LOOP = 8;
static const int32_t PRE_LOOP = 8;

// Define the size of the state array:
static const int32_t N = 4;

// Define shift constants:
static const int32_t SH0 = 1;
static const int32_t SH1 = 10;
static const int32_t SH8 = 8;

// Define a mask: 127 (0x7f)
static const uint32_t MASK = 0x7f;

// Define the default values for mat1, mat2, and tmat:
static const uint32_t DEFAULT_MAT1 = 0x8f7011ee;
static const uint32_t DEFAULT_MAT2 = 0xfc78ff1f;
static const uint32_t DEFAULT_TMAT = 0x3793fdff;

// Define the maximum unsigned 32-bit integer: 4294967295 => 11111111111111111111111111111111
static const uint32_t MAX_UINT32 = 4294967295;

// Define the maximum "safe" double-precision floating-point integer:
#define FLOAT64_MAX_SAFE_INTEGER 9007199254740991.0

// Define a normalization constant when generating double-precision floating-point numbers: 2^53 => 9007199254740992
#define FLOAT64_NORMALIZATION_CONSTANT (1.0 / (FLOAT64_MAX_SAFE_INTEGER + 1.0))

// Define the maximum normalized value
#define MAX_NORMALIZED (FLOAT64_MAX_SAFE_INTEGER / (FLOAT64_MAX_SAFE_INTEGER + 1.0))

/**
* TinyMT32 PRNG.
*
*/
static const struct BasePRNG tinymt32_prng = {
	"tinymt32",                                           // name
	(uint64_t)0,                                          // min
	(uint64_t)MAX_UINT32,                                 // max: (2^{32}-1)
	0.0,                                                  // min (normalized)
	MAX_NORMALIZED,                                       // max (normalized): (2^{53}-1)/2^{53}
	sizeof( stdlib_base_random_tinymt32_state_t ),        // state_size
	&next,                                                // next()
	&normalized,                                          // normalized()
	&tinymt32_free                                        // free()
};

/**
* Initialize the state of a TinyMT32 PRNG.
*
* @param state   state array (array of 4 uint32_t values)
* @param s       seed
*/
static inline void create_state( uint32_t *state, uint32_t s ) {
	int32_t i;
	const uint32_t knuth_multiplier = 1812433253;

	// Set the initial state values
	state[ 0 ] = s;
	state[ 1 ] = DEFAULT_MAT1;
	state[ 2 ] = DEFAULT_MAT2;
	state[ 3 ] = DEFAULT_TMAT;

	// Initialize using the algorithm from tinymt32_init
	for ( i = 1; i < MIN_LOOP; i++ ) {
		state[ i & 3 ] ^= i + knuth_multiplier *
			(state[(i - 1) & 3] ^ (state[(i - 1) & 3] >> 30));
	}

	// Pre-run the algorithm to improve randomness of the initial state
	for ( i = 0; i < PRE_LOOP; i++ ) {
		next_state( state, DEFAULT_MAT1, DEFAULT_MAT2, DEFAULT_TMAT );
	}
}

/**
* Update the state array of a TinyMT32 PRNG.
*
* ## Notes
*
* This is the state transition function.
*
* @param state   state array (array of 4 uint32_t values)
* @param mat1    parameter matrix 1
* @param mat2    parameter matrix 2
* @param tmat    parameter tmat
*/
static inline void next_state( uint32_t *state, uint32_t mat1, uint32_t mat2, uint32_t tmat ) {
	uint32_t x;
	uint32_t y;

	// Mix state
	y = state[3];
	x = (state[0] & MASK) ^ state[1] ^ state[2];
	x ^= (x << SH0);
	y ^= (y >> SH0) ^ x;
	state[0] = state[1];
	state[1] = state[2];
	state[2] = x ^ (y << SH1);
	state[3] = y;

	// Apply the tempering
	if (y & 1) {
		state[1] ^= mat1;
		state[2] ^= mat2;
	}
}

/**
* Generate a tempered output from the current state.
*
* @param state   state array (array of 4 uint32_t values)
* @param mat1    parameter matrix 1
* @param mat2    parameter matrix 2
* @param tmat    parameter tmat
* @return        tempered output
*/
static inline uint32_t temper( const uint32_t *state, uint32_t mat1, uint32_t mat2, uint32_t tmat ) {
	uint32_t t0, t1;

	// Tempering
	t0 = state[3];
	t1 = state[0] + (state[2] >> SH8);
	t0 ^= t1;

	if (t1 & 1) {
		t0 ^= tmat;
	}

	return t0;
}

/**
* Returns a pseudorandom 32-bit unsigned integer.
*
* @param obj     PRNG object
* @param out     output address
* @return        status code
*/
static inline int8_t next( struct BasePRNGObject *obj, uint64_t *out ) {
	stdlib_base_random_tinymt32_state_t *state;
	uint32_t u;

	state = (stdlib_base_random_tinymt32_state_t *)( obj->state );
	next_state( state->state, state->mat1, state->mat2, state->tmat );
	u = temper( state->state, state->mat1, state->mat2, state->tmat );
	*out = (uint64_t)u;
	return 0;
}

/**
* Returns a pseudorandom double-precision floating-point number on the interval `[0,1)`.
*
* @param obj     PRNG object
* @param out     output address
* @return        status code
*/
static inline int8_t normalized( struct BasePRNGObject *obj, double *out ) {
	uint64_t u;
	stdlib_base_random_tinymt32_state_t *state;

	next( obj, &u );
	state = (stdlib_base_random_tinymt32_state_t *)( obj->state );
	u = temper( state->state, state->mat1, state->mat2, state->tmat );
	*out = (double)u * FLOAT64_NORMALIZATION_CONSTANT;
	return 0;
}

/**
* Frees a TinyMT32 PRNG's allocated memory.
*
* @param obj     PRNG object
*/
static inline void tinymt32_free( struct BasePRNGObject *obj ) {
	if ( obj == NULL || obj->state == NULL ) {
		return;
	}
	free( obj->state );
	free( obj );
}

/**
* Returns a pointer to a dynamically allocated TinyMT32 PRNG.
*
* ## Notes
*
* -   The function returns a pointer to a dynamically allocated PRNG whose memory must be explicitly freed.
* -   The function returns a pointer to a PRNG having the following properties:
*
*     - 32-bit unsigned integer domain
*     - jump:
*
* @param seed    PRNG seed
* @return        pointer to a dynamically allocated PRNG or NULL
*
* @example
* #include <stdlib.h>
* #include <stdio.h>
* #include <stdint.h>
* #include "stdlib/random/base/tinymt32.h"
*
* // Create a PRNG:
* struct BasePRNGObject *obj = stdlib_base_random_tinymt32_allocate( 12345 );
* if ( obj == NULL ) {
*     fprintf( stderr, "Error allocating PRNG.\n" );
*     exit( 1 );
* }
*
* uint64_t r;
* int8_t status = obj->prng->next( obj, &r );
* if ( status != 0 ) {
*     fprintf( stderr, "Error generating pseudorandom number.\n" );
*     exit( 1 );
* }
*
* // ...
*
* // Free allocated memory:
* obj->prng->free( obj );
*/
struct BasePRNGObject *stdlib_base_random_tinymt32_allocate( const uint32_t seed ) {
	stdlib_base_random_tinymt32_state_t *state;
	struct BasePRNGObject *obj;

	obj = malloc( sizeof( struct BasePRNGObject ) );
	if ( obj == NULL ) {
		return NULL;
	}
	state = malloc( sizeof( stdlib_base_random_tinymt32_state_t ) );
	if ( state == NULL ) {
		free( obj );
		return NULL;
	}
	obj->prng = &tinymt32_prng;
	obj->state = state;

	state->mat1 = DEFAULT_MAT1;
	state->mat2 = DEFAULT_MAT2;
	state->tmat = DEFAULT_TMAT;

	create_state( state->state, seed );

	return obj;
}
